module dice_optimal_reroll (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] K,\n    input [7:0] T,\n    input [23:0] dice_in,\n    output reg [3:0] result,\n    output reg done\n);\n\n    localparam [2:0] STATE_IDLE = 3'd0;\n    localparam [2:0] STATE_COMPUTE_S = 3'd1;\n    localparam [2:0] STATE_ITERATE = 3'd2;\n    localparam [2:0] STATE_UPDATE_BEST = 3'd3;\n    localparam [2:0] STATE_FIND_RESULT = 3'd4;\n\n    reg [2:0] state;\n    reg [3:0] current_K;\n    reg [7:0] current_T;\n    reg [23:0] current_dice;\n    reg [7:0] S;\n    reg [7:0] delta;\n    reg [7:0] subset_counter;\n    reg [3:0] best_R;\n    reg [21:0] best_ways;\n    reg [21:0] current_ways;\n    reg [3:0] current_R;\n    reg [7:0] X;\n    reg [7:0] Y;\n    reg [7:0] dice_sum;\n    reg [2:0] die_idx;\n\n    reg [21:0] ways_table [0:8][0:48];\n\n    integer r, y;\n    always @(posedge clk) begin\n        if (!rst_n) begin\n            for (r = 0; r <= 8; r = r + 1) begin\n                for (y = 0; y <= 48; y = y + 1) begin\n                    if (r == 0 && y == 0) ways_table[r][y] <= 22'd1;\n                    else if (r == 1 && y >= 1 && y <= 6) ways_table[r][y] <= 22'd1;\n                    else ways_table[r][y] <= 22'd0;\n                end\n            end\n        end else begin\n            // Precomputed values for R=2\n            if (2 <= K) begin\n                ways_table[2][2] <= 22'd1;\n                ways_table[2][3] <= 22'd2;\n                ways_table[2][4] <= 22'd3;\n                ways_table[2][5] <= 22'd4;\n                ways_table[2][6] <= 22'd5;\n                ways_table[2][7] <= 22'd6;\n                ways_table[2][8] <= 22'd5;\n                ways_table[2][9] <= 22'd4;\n                ways_table[2][10] <= 22'd3;\n                ways_table[2][11] <= 22'd2;\n                ways_table[2][12] <= 22'd1;\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= STATE_IDLE;\n            done <= 1'b0;\n            result <= 4'd0;\n            best_R <= 4'd8;\n            best_ways <= 22'd0;\n            subset_counter <= 8'd0;\n            S <= 8'd0;\n            delta <= 8'd0;\n            current_dice <= 24'd0;\n            X <= 8'd0;\n            Y <= 8'd0;\n        end else begin\n            case (state)\n                STATE_IDLE: begin\n                    done <= 1'b0;\n                    best_ways <= 22'd0;\n                    best_R <= K;  // Worst case R=K\n                    if (start) begin\n                        current_K <= K;\n                        current_T <= T;\n                        current_dice <= dice_in;\n                        S <= 8'd0;\n                        die_idx <= 3'd0;\n                        state <= STATE_COMPUTE_S;\n                    end\n                end\n\n                STATE_COMPUTE_S: begin\n                    if (die_idx < current_K) begin\n                        S <= S + current_dice[die_idx*3 +: 3];\n                        die_idx <= die_idx + 3'd1;\n                    end else begin\n                        delta <= current_T - S;\n                        subset_counter <= 8'd0;\n                        state <= STATE_ITERATE;\n                    end\n                end\n\n                STATE_ITERATE: begin\n                    if (subset_counter < (1 << current_K)) begin\n                        X <= 8'd0;\n                        current_R <= 4'd0;\n                        die_idx <= 3'd0;\n                        state <= STATE_UPDATE_BEST;\n                    end else begin\n                        state <= STATE_FIND_RESULT;\n                    end\n                end\n\n                STATE_UPDATE_BEST: begin\n                    if (die_idx < current_K) begin\n                        if (subset_counter[die_idx]) begin\n                            X <= X + current_dice[die_idx*3 +: 3];\n                            current_R <= current_R + 4'd1;\n                        end\n                        die_idx <= die_idx + 3'd1;\n                    end else begin\n                        Y <= delta + X;\n                        if (Y >= current_R && Y <= current_R * 8'd6 && current_R <= current_K) begin\n                            current_ways <= ways_table[current_R][Y];\n                        end else begin\n                            current_ways <= 22'd0;\n                        end\n                        subset_counter <= subset_counter + 8'd1;\n\n                        if ((current_ways > best_ways) || \n                            (current_ways == best_ways && current_R < best_R)) begin\n                            best_ways <= current_ways;\n                            best_R <= current_R;\n                        end\n                        \n                        state <= STATE_ITERATE;\n                    end\n                end\n\n                STATE_FIND_RESULT: begin\n                    result <= best_R;\n                    done <= 1'b1;\n                    state <= STATE_IDLE;\n                end\n\n                default: state <= STATE_IDLE;\n            endcase\n        end\n    end\n\nendmodule